    keywords: "",
    excerpt: "",
    content: `<p>Getting stuck in an elevator is one of those things that we all hope to avoid, unfortunately, it can&#39;t be avoided. Everyone&#39;s worst nightmare is getting stuck in an elevator. The emergency call button in front of you is your sole source of support as you hang several stories above the ground.&nbsp;</p>

<p>While there are ethics issued by the Bureau of India Standards, these serve as rules  &  are only mandatory if endorsed by the state legislation. &ldquo;Industry bodies like the Bureau of Indian Standards are trying to change this by driving required safety standards for the elevator industry  &  looking for co-operation from the states.&nbsp;</p>

<p><strong>If a person uses an</strong><a href="https://news.abplive.com/lifestyle/stuck-in-an-elevator-heres-how-to-get-out-of-lift-that-has-stopped-in-between-floors-or-jammed-1382546"><strong> </strong><strong>elevator every day</strong></a><strong>, the odds are a 1 in 5,000 chance of getting stuck each month. If the person rides an elevator every workday for 25 years, your chances increase to 1 in 17 times.</strong></p>

<p><strong>﻿Elevators are safe, and the possibility of harm in one is very unlikely. The U.S.</strong><a href="https://www.facilitiesnet.com/elevators/article.aspx?id=13199"><strong> </strong><strong>Bureau of Labor Statistics reports</strong></a><strong> that there are about 27 fatalities per 18 billion usage each year. Accordingly, there is a 0.00000015 percent chance of dying while riding an elevator.</strong>&nbsp;</p>

<p>Are you looking for the right steps to follow while you are stuck in an elevator? If you ever find yourself stuck in an elevator make sure you follow these simple tips to remove the fear of getting stuck in an elevator and make the experience less of a headache.</p>

<p>1. <strong>Stay Calm&nbsp;</strong></p>

<p>If you&#39;re stuck inside an elevator, it&#39;s important to stay calm. The first thing you should do is try to make sure that no one is injured. Try to check on the health of other passengers in the elevator and get them to safety as quickly as possible. There is no actual need to panic when stuck in an elevator, just take a deep breath and think about how best to approach your next steps. Then proceed with confidence knowing that everything is going to be alright. The professionals will arrive soon to take care of the situation.&nbsp;</p>

<p>For some reason, people always seem to panic in an elevator, when really they are just stuck inside. No one is stuck inside and there is absolutely nothing dangerous about being stuck in an elevator, so just keep telling yourself &quot;I&#39;m stuck not trapped&quot;.&nbsp;</p>

<p><strong>2. Use the Emergency Phone</strong></p>

<p>After that, look for a way to signal the elevator&#39;s location and call for help. You can also use the elevator&#39;s emergency phone as soon as possible. Theoretically, each elevator should be equipped with an emergency phone that may be used to contact the building&#39;s security or the elevator company. Locate the proper person using the phone; make sure to give them your name, the address of the facility you&#39;re in, and a description of the issue at hand.</p>

<p>As it may be difficult to get a signal in some elevators, there are additional ways to contact emergency services if you find yourself stuck inside:</p>

<p>●&nbsp; &nbsp; If the elevator has an external camera, turn it toward the ground floor level so that emergency responders can see where you are.&nbsp;</p>

<p>● &nbsp; No matter how quickly emergency personnel is called it will still take time for them to arrive and solve the issue. Try to unwind and settle in for the meantime. Never ever attempt to leave a stalled lift car since it could be very harmful. The most crucial thing to remember when you are stuck in an elevator is to be calm and safe until assistance arrives.</p>

<p><strong>3. Press the Alarm Button&nbsp;</strong></p>

<p>An elevator&#39;s alarm button sounds to let people know when someone is stuck within and needs help. Ringing the bell periodically could be helpful if the call button isn&#39;t functioning and the maintenance crew cannot be reached. It&#39;s extremely likely that someone within the building will hear the alarm and call for help.</p>

<p><strong>4. Remember You are Safe</strong>&nbsp;</p>

<p>It&#39;s crucial to keep in mind that you are completely safe while you wait for assistance. The operators of elevators go to tremendous measures to guarantee the security of their customers. Yes, it&#39;s possible that you&#39;ll be late for work or your next appointment. However, a lot of individuals get stuck in elevators every year, and most of the time it&#39;s only a little annoyance. So always remember that you are safe!&nbsp;</p>

<p><strong>5. Wait</strong></p>

<p>You have a great probability of escaping the apartment elevator in a few minutes even if you take none of the aforementioned actions. The elevator&#39;s malfunction will be quickly noticed by others across the building, who will then call for help.</p>

<p>Wait if you&#39;ve been able to reach maintenance or emergency personnel. Calls reporting elevator apartments are taken seriously, and you&#39;ll probably be released in 30 minutes or less.</p>

<p>Thus, these are some steps you can take if you are stuck in an elevator!&nbsp;</p>`,
